package fs

import (
	"context"
	"errors"
	"net/http"
	"syscall"

	"agent-memory-fuse/internal/client"
)

func errnoFor(err error) syscall.Errno {
	if err == nil {
		return 0
	}
	// go-fuse cancels the request context for FUSE_INTERRUPT, including the
	// SIGURG interrupts generated by Go runtime preemption. Returning EINTR
	// lets normal POSIX callers retry instead of exposing a spurious EIO.
	if errors.Is(err, context.Canceled) {
		return syscall.EINTR
	}
	if errors.Is(err, ErrTooLarge) {
		return syscall.EFBIG
	}
	if errors.Is(err, ErrInvalidUTF8) {
		return syscall.EILSEQ
	}
	var apiErr *client.APIError
	if errors.As(err, &apiErr) {
		// Code 优先（设计 §5.4）：服务端把 409 细分为独立 code，客户端不再
		// 靠裸状态码/描述文案猜语义。
		switch apiErr.Code {
		case "FILE_MEMORY_ARCHIVED", "READ_ONLY_STORE":
			// READ_ONLY_STORE：服务端把 file+ots 投影库判定为只读，
			// 所有写端点返回 409 该 code，语义上等同只读文件系统。
			// FILE_MEMORY_ARCHIVED：历史保留码，当前服务端不再产生。
			return syscall.EROFS
		case "QUOTA_EXCEEDED":
			return syscall.ENOSPC
		case "PRECONDITION_FAILED": // 资源版本已变更或目标已删除
			return syscall.ESTALE
		case "SHA_MISMATCH": // 历史 CAS 失败码：旧 handle 已过期
			return syscall.ESTALE
		case "PATH_EXISTS": // 路径占用（create 重名 / rename !overwrite）
			return syscall.EEXIST
		case "LOCK_CONFLICT": // 局部事务锁冲突：瞬时，可重试
			return syscall.EAGAIN
		}
		switch apiErr.StatusCode {
		case http.StatusBadRequest:
			return syscall.EINVAL
		case http.StatusUnauthorized, http.StatusForbidden:
			// 鉴权失败(典型来源:STS 临时凭证过期):映射 EACCES 而非落入
			// default 的 EIO,让"需换凭证重挂"与网络故障在用户侧可区分。
			return syscall.EACCES
		case http.StatusNotFound:
			return syscall.ENOENT
		case http.StatusConflict:
			return syscall.ESTALE
		case http.StatusRequestEntityTooLarge:
			return syscall.EFBIG
		case http.StatusTooManyRequests, http.StatusServiceUnavailable, http.StatusGatewayTimeout:
			return syscall.EAGAIN
		default:
			return syscall.EIO
		}
	}
	return syscall.EIO
}
